// ---- Utilidades (se repiten en cada nodo para que cada uno sea autosuficiente) ----
const TZ = 'America/Argentina/Buenos_Aires';
const txt = a => (a || []).map(t => t.plain_text).join('');
const sel = p => (p && (p.status || p.select)) ? (p.status || p.select).name : '';
const CALIDAD = ['Una idea y gancho', 'Fuente y permiso', 'Corregido otro día', 'Tamaño correcto'];
function leer(page) {
  const p = page.properties || {};
  const fecha = p['Fecha de publicación'] && p['Fecha de publicación'].date ? p['Fecha de publicación'].date.start : '';
  return {
    pageId: page.id,
    pageUrl: page.url,
    titulo: txt(p['Contenido'] && p['Contenido'].title),
    estado: sel(p['Estado']),
    tipo: sel(p['Tipo']),
    plataformas: ((p['Plataforma'] && p['Plataforma'].multi_select) || []).map(o => o.name),
    fecha,
    ganchoCopy: txt(p['Gancho y Copy'] && p['Gancho y Copy'].rich_text),
    enlaceCanva: (p['Enlace Canva'] && p['Enlace Canva'].url) || '',
    archivo: (p['Archivo en Drive'] && p['Archivo en Drive'].url) || '',
    enlacePost: (p['Enlace del post'] && p['Enlace del post'].url) || '',
    errorActual: txt(p['Error'] && p['Error'].rich_text),
    calidad: CALIDAD.map(k => !!(p[k] && p[k].checkbox)),
  };
}
const slug = s => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40).replace(/-+$/g, '') || 'sin-titulo';
const SOPORTADAS = ['Instagram', 'LinkedIn', 'X'];

const MODO_PRUEBA = String($env.MODO_PRUEBA ?? 'true').toLowerCase() !== 'false'; // cualquier valor distinto de "false" = prueba
const MAX_HASHTAGS = 3, MAX_EMOJIS = 2;
const LIMITE = { x: 280, linkedin: 3000, instagram: 2200 };

const p = leer($input.first().json);
const salir = (motivo, prefijo) => [{ json: { ...p, valido: false, modoPrueba: MODO_PRUEBA, motivo: (prefijo || 'BLOQUEADO') + ': ' + motivo } }];

if (p.estado !== 'Aprobado') return salir('Estado no es Aprobado.');
if (!p.calidad.every(Boolean)) return salir('faltan casillas de calidad.');
if (!p.fecha) return salir('falta Fecha de publicación.');
if (DateTime.fromISO(p.fecha, { zone: TZ }) > DateTime.now()) return salir('todavía no es la fecha de publicación.');
if (p.enlacePost) return salir('ya tiene "Enlace del post" (posible duplicado).');

const plats = p.plataformas.filter(x => SOPORTADAS.includes(x));
if (plats.length !== 1) return salir(plats.length ? 'una pieza = una plataforma (duplicá la fila).' : 'sin plataforma soportada.');
const plataforma = plats[0];

const RUTAS = {
  'Instagram|Post': 'instagram', 'Instagram|Carrusel': 'instagram', 'Instagram|Flyer': 'instagram',
  'LinkedIn|Carrusel': 'linkedin_pdf', 'LinkedIn|Post': 'linkedin_imagen', 'LinkedIn|Flyer': 'linkedin_imagen',
  'X|Post': 'x_imagen', 'X|Flyer': 'x_imagen', 'X|Hilo': 'x_hilo',
};
if (plataforma === 'Instagram' && p.tipo === 'Story') {
  return salir('Story de Instagram: publicar a mano (este prototipo no la automatiza). Archivo: ' + (p.archivo || 'sin archivo'), 'MANUAL IG');
}
const ruta = RUTAS[plataforma + '|' + p.tipo];
if (!ruta) return salir('combinación no soportada: ' + plataforma + ' + ' + p.tipo + '.');

const necesitaArchivo = ruta !== 'x_hilo';
if (necesitaArchivo && !p.archivo) return salir('falta "Archivo en Drive" (corré el flujo A).');
const esCarpeta = /drive\.google\.com\/drive\/(u\/\d+\/)?folders\//.test(p.archivo);
const m = p.archivo.match(/\/folders\/([A-Za-z0-9_-]+)/) || p.archivo.match(/\/d\/([A-Za-z0-9_-]+)/) || p.archivo.match(/[?&]id=([A-Za-z0-9_-]+)/);
const fileId = m ? m[1] : '';
if (necesitaArchivo && !fileId) return salir('no pude leer el ID de Drive desde "Archivo en Drive".');
if (esCarpeta && ruta !== 'instagram') return salir('"Archivo en Drive" es una carpeta pero esta ruta espera un solo archivo.');

// Texto: se publica tal cual está en Notion (no se inventa nada)
const texto = p.ganchoCopy.trim();
if (!texto) return salir('"Gancho y Copy" está vacío.');
const partes = ruta === 'x_hilo' ? texto.split(/\n\s*-{3,}\s*\n/).map(s => s.trim()).filter(Boolean) : [texto];
const hashtags = (texto.match(/#[\p{L}\p{N}_]+/gu) || []).length;
const emojis = (texto.match(/\p{Extended_Pictographic}/gu) || []).length;
if (hashtags > MAX_HASHTAGS) return salir('demasiados hashtags (' + hashtags + ', máximo ' + MAX_HASHTAGS + ').');
if (emojis > MAX_EMOJIS) return salir('demasiados emojis (' + emojis + ', máximo ' + MAX_EMOJIS + ').');
const lim = plataforma === 'X' ? LIMITE.x : plataforma === 'LinkedIn' ? LIMITE.linkedin : LIMITE.instagram;
const largo = Math.max(...partes.map(s => [...s].length));
if (largo > lim) return salir('el texto supera el límite de ' + plataforma + ' (' + largo + ' > ' + lim + ').');
if (ruta === 'x_hilo' && partes.length < 2) return salir('un hilo necesita al menos 2 partes separadas por una línea con ---.');

// LinkedIn (API Posts, "little text format"): se escapan los caracteres reservados, menos #
const textoLinkedIn = texto.replace(/[\\|{}@\[\]()<>*_~]/g, c => '\\' + c);

return [{ json: {
  ...p, valido: true, modoPrueba: MODO_PRUEBA, plataforma, ruta, necesitaArchivo, esCarpeta, fileId,
  texto, textoLinkedIn, partes,
  nombreBase: DateTime.fromISO(p.fecha, { zone: TZ }).toFormat('yyyy-LL-dd') + '_' + plataforma + '_' + p.tipo + '_' + slug(p.titulo),
} }];

let prev = '';
try { if ($('X: publicar respuesta').isExecuted) prev = $('X: publicar respuesta').last().json.id; } catch (e) {}
if (!prev) { try { if ($('X: publicar primer tuit').isExecuted) prev = $('X: publicar primer tuit').last().json.id; } catch (e) {} }
return [{ json: { ...$json, replyTo: prev } }];

const ctx = $('Validar pieza y elegir ruta').first().json;
let ids;
if (ctx.esCarpeta) {
  ids = $('Drive: listar imágenes de la carpeta').all().map(i => i.json)
    .filter(f => /image\/jpeg/.test(f.mimeType || '') || /\.jpe?g$/i.test(f.name || ''))
    .sort((a, b) => String(a.name).localeCompare(String(b.name))).map(f => f.id);
} else ids = [ctx.fileId];
if (!ids.length) throw new Error('No hay imágenes JPG en la carpeta de Drive.');
if (ids.length > 10) throw new Error('Instagram admite hasta 10 imágenes por carrusel (hay ' + ids.length + ').');
return ids.map((id, i) => ({ json: { fileId: id, orden: i + 1, total: ids.length } }));

const ctx = $('Validar pieza y elegir ruta').first().json;
return $('IG: preparar lista de imágenes').all().map(i => ({ json: {
  image_url: 'https://drive.google.com/uc?export=download&id=' + i.json.fileId,
  orden: i.json.orden, total: i.json.total, caption: i.json.total > 1 ? '' : ctx.texto, hijo: i.json.total > 1 } }));

const ctx = $('Validar pieza y elegir ruta').first().json;
const items = $input.all().map(i => i.json);
const fallo = items.find(i => i.error || !i.id);
if (fallo) return [{ json: { ok: false, detalle: JSON.stringify(fallo.error || fallo).slice(0, 400) } }];
return [{ json: items.length > 1 ? { ok: true, carrusel: true, children: items.map(i => i.id).join(','), caption: ctx.texto }
                                  : { ok: true, carrusel: false, id: items[0].id } }];

const ctx = $('Validar pieza y elegir ruta').first().json;
const base = 'https://storage.googleapis.com/' + $env.IG_PUBLIC_BUCKET + '/';
return $('IG: lista de imágenes para el hosting público').all().map(i => ({ json: {
  image_url: base + 'ig/' + ctx.pageId + '/' + i.json.orden + '.jpg',
  orden: i.json.orden, total: i.json.total, caption: i.json.total > 1 ? '' : ctx.texto, hijo: i.json.total > 1 } }));

const ctx = $('Validar pieza y elegir ruta').first().json;
const items = $input.all().map(i => i.json);
const fallo = items.find(i => i.error || !i.id);
if (fallo) return [{ json: { ok: false, detalle: JSON.stringify(fallo.error || fallo).slice(0, 400) } }];
return [{ json: items.length > 1 ? { ok: true, carrusel: true, children: items.map(i => i.id).join(','), caption: ctx.texto }
                                  : { ok: true, carrusel: false, id: items[0].id } }];

const st = $json.status_code;
if (st !== 'FINISHED') throw new Error('El contenedor de Instagram no quedó listo (status_code=' + st + ').');
return [{ json: { creation_id: $json.id } }];

const ctx = $('Validar pieza y elegir ruta').first().json;
let enlace = '';
if (ctx.ruta === 'instagram') enlace = $('IG: obtener enlace del post').first().json.permalink;
else if (ctx.ruta === 'linkedin_imagen') enlace = 'https://www.linkedin.com/feed/update/' + $('LinkedIn: publicar imagen').first().json.id + '/';
else if (ctx.ruta === 'linkedin_pdf') enlace = 'https://www.linkedin.com/feed/update/' + ($('LinkedIn: crear post con el PDF').first().json.headers['x-restli-id']) + '/';
else if (ctx.ruta === 'x_imagen') enlace = 'https://x.com/i/status/' + $('X: publicar tuit con imagen').first().json.id;
else if (ctx.ruta === 'x_hilo') enlace = 'https://x.com/i/status/' + $('X: publicar primer tuit').first().json.id;
if (!enlace) throw new Error('Se publicó pero no pude obtener el enlace del post. Revisar a mano.');
return [{ json: { pageId: ctx.pageId, enlace } }];

const ctx = $('Validar pieza y elegir ruta').first().json;
const e = $json.error;
let msg = typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify($json).slice(0, 400);
if (e && e.node && e.node.name) msg = '[' + e.node.name + '] ' + msg;
// Si un hilo ya publicó el primer tuit, reintentar duplicaría tuits: pasa a manual.
let parcial = false;
if (ctx.ruta === 'x_hilo') { try { parcial = $('X: publicar primer tuit').isExecuted; } catch (x) {} }
if (parcial) return [{ json: { pageId: ctx.pageId, texto: ('MANUAL X: el hilo quedó publicado a medias (no se reintenta para no duplicar). ' + msg).slice(0, 1800) } }];
const m = (ctx.errorActual || '').match(/^ERROR \(intento (\d)\/3\)/);
const n = (m ? parseInt(m[1], 10) : 0) + 1;
const texto = (n >= 3 ? 'REINTENTOS AGOTADOS (3/3): ' : 'ERROR (intento ' + n + '/3): ') + msg;
return [{ json: { pageId: ctx.pageId, texto: texto.slice(0, 1800) } }];
